export function threeSumZero(numbers) {
    const a = [...numbers].sort((x, y) => x - y);
    const out = [];
    for (let i = 0; i < a.length - 2; i++) {
        if (i > 0 && a[i] === a[i - 1])
            continue;
        if (a[i] > 0)
            break;
        let left = i + 1, right = a.length - 1;
        while (left < right) {
            const sum = a[i] + a[left] + a[right];
            if (sum < 0)
                left++;
            else if (sum > 0)
                right--;
            else {
                out.push([a[i], a[left], a[right]]);
                left++;
                right--;
                while (left < right && a[left] === a[left - 1])
                    left++;
                while (left < right && a[right] === a[right + 1])
                    right--;
            }
        }
    }
    return out;
}
